//! Lookups over the vendored Unicode 16.0 tables ([`crate::unicode_tables`], generated by
//! `compiler/tools/gen_unicode_tables.py`, FOUNDER-QUEUE Q18) and the NFC check behind
//! SEC0101 (spec §4.1, §5.1).
//!
//! NFC follows UAX #15: full canonical decomposition (Hangul algorithmically), canonical
//! ordering by combining class, then canonical composition of primary composites. The
//! check splits the text before every character that has combining class 0 and
//! `NFC_Quick_Check = Yes`, a point no normalization step crosses, so each segment can be
//! normalized and compared on its own. Python's `unicodedata.normalize` is the oracle:
//! the generated vectors in `nfc_vectors.rs` must be reproduced exactly.

use std::cmp::Ordering;

use crate::unicode_tables::{
    COMBINING_CLASS, COMPOSITION, DECOMPOSITION, EXTENDED_PICTOGRAPHIC, NFC_QC_MAYBE, NFC_QC_NO,
    UNASSIGNED,
};

// Hangul syllables (Unicode §3.12).
const S_BASE: u32 = 0xAC00;
const L_BASE: u32 = 0x1100;
const V_BASE: u32 = 0x1161;
const T_BASE: u32 = 0x11A7;
const L_COUNT: u32 = 19;
const V_COUNT: u32 = 21;
const T_COUNT: u32 = 28;
const N_COUNT: u32 = V_COUNT * T_COUNT;
const S_COUNT: u32 = L_COUNT * N_COUNT;

fn in_ranges(table: &[(u32, u32)], c: char) -> bool {
    let n = c as u32;
    table
        .binary_search_by(|&(lo, hi)| {
            if hi < n {
                Ordering::Less
            } else if lo > n {
                Ordering::Greater
            } else {
                Ordering::Equal
            }
        })
        .is_ok()
}

fn scalar(n: u32) -> char {
    char::from_u32(n).unwrap_or(char::REPLACEMENT_CHARACTER)
}

/// General_Category = Cn in Unicode 16.0 (noncharacters included): SEC0112. Rust's own
/// `char` properties follow a newer Unicode, so this is asked before them.
pub(crate) fn is_unassigned(c: char) -> bool {
    !c.is_ascii() && in_ranges(UNASSIGNED, c)
}

/// `Extended_Pictographic` (emoji-data), for the §5.1 emoji exceptions.
pub(crate) fn is_extended_pictographic(c: char) -> bool {
    !c.is_ascii() && in_ranges(EXTENDED_PICTOGRAPHIC, c)
}

/// Canonical_Combining_Class.
pub(crate) fn combining_class(c: char) -> u8 {
    if c.is_ascii() {
        return 0;
    }
    let n = c as u32;
    COMBINING_CLASS
        .binary_search_by(|&(lo, hi, _)| {
            if hi < n {
                Ordering::Less
            } else if lo > n {
                Ordering::Greater
            } else {
                Ordering::Equal
            }
        })
        .map_or(0, |i| COMBINING_CLASS[i].2)
}

/// No normalization step crosses the point before `c`: combining class 0 and
/// `NFC_Quick_Check = Yes` (it never composes with what precedes it).
fn is_boundary(c: char) -> bool {
    c.is_ascii()
        || (combining_class(c) == 0 && !in_ranges(NFC_QC_NO, c) && !in_ranges(NFC_QC_MAYBE, c))
}

fn decompose(c: char, out: &mut Vec<char>) {
    let n = c as u32;
    if (S_BASE..S_BASE + S_COUNT).contains(&n) {
        let s = n - S_BASE;
        out.push(scalar(L_BASE + s / N_COUNT));
        out.push(scalar(V_BASE + (s % N_COUNT) / T_COUNT));
        if s % T_COUNT != 0 {
            out.push(scalar(T_BASE + s % T_COUNT));
        }
        return;
    }
    match DECOMPOSITION.binary_search_by_key(&n, |&(cp, _, _)| cp) {
        Ok(i) => {
            let (_, first, second) = DECOMPOSITION[i];
            decompose(scalar(first), out);
            if second != 0 {
                decompose(scalar(second), out);
            }
        }
        Err(_) => out.push(c),
    }
}

fn compose(a: char, b: char) -> Option<char> {
    let (a, b) = (a as u32, b as u32);
    if (L_BASE..L_BASE + L_COUNT).contains(&a) && (V_BASE..V_BASE + V_COUNT).contains(&b) {
        let lv = S_BASE + ((a - L_BASE) * V_COUNT + (b - V_BASE)) * T_COUNT;
        return Some(scalar(lv));
    }
    if (S_BASE..S_BASE + S_COUNT).contains(&a)
        && (a - S_BASE) % T_COUNT == 0
        && (T_BASE + 1..T_BASE + T_COUNT).contains(&b)
    {
        return Some(scalar(a + (b - T_BASE)));
    }
    COMPOSITION
        .binary_search_by_key(&(a, b), |&(x, y, _)| (x, y))
        .ok()
        .map(|i| scalar(COMPOSITION[i].2))
}

/// The NFC form of `s`.
pub(crate) fn nfc(s: &str) -> String {
    let mut d = Vec::with_capacity(s.len());
    for c in s.chars() {
        decompose(c, &mut d);
    }
    // Canonical ordering: a stable sort by combining class within each run of non-starters.
    let mut i = 0;
    while i < d.len() {
        if combining_class(d[i]) == 0 {
            i += 1;
            continue;
        }
        let start = i;
        while i < d.len() && combining_class(d[i]) != 0 {
            i += 1;
        }
        d[start..i].sort_by_key(|&c| combining_class(c));
    }
    // Canonical composition.
    let mut out: Vec<char> = Vec::with_capacity(d.len());
    let mut starter: Option<usize> = None;
    let mut last_class = 0u8;
    for c in d {
        let class = combining_class(c);
        if let Some(si) = starter {
            let adjacent = out.len() == si + 1;
            let blocked = !adjacent && (last_class == 0 || last_class >= class);
            if !blocked {
                if let Some(composite) = compose(out[si], c) {
                    out[si] = composite;
                    continue;
                }
            }
        }
        if class == 0 {
            starter = Some(out.len());
        }
        last_class = class;
        out.push(c);
    }
    out.into_iter().collect()
}

/// A run of text that is not in NFC (SEC0101): chars `start..end` of the scanned text,
/// their NFC form, and the code point the diagnostic names.
pub(crate) struct NotNfc {
    pub start: usize,
    pub end: usize,
    pub nfc: String,
    pub cp: char,
}

/// Every run of `chars` (a whole file, as `char_indices`) that is not in NFC, each trimmed
/// to the characters normalization changes.
pub(crate) fn not_nfc(chars: &[(usize, char)]) -> Vec<NotNfc> {
    let mut out = Vec::new();
    let mut i = 0;
    while i < chars.len() {
        let mut j = i + 1;
        while j < chars.len() && !is_boundary(chars[j].1) {
            j += 1;
        }
        // A lone stable character (most of any file) needs no normalization or allocation.
        if j > i + 1 || !is_boundary(chars[i].1) {
            out.extend(check_segment(&chars[i..j], i));
        }
        i = j;
    }
    out
}

/// One segment (`at` is the index of its first char), trimmed to what NFC changes.
fn check_segment(chars: &[(usize, char)], at: usize) -> Option<NotNfc> {
    let seg: Vec<char> = chars.iter().map(|&(_, c)| c).collect();
    let normal: Vec<char> = nfc(&seg.iter().collect::<String>()).chars().collect();
    if normal == seg {
        return None;
    }
    let prefix = seg.iter().zip(&normal).take_while(|(a, b)| a == b).count();
    let suffix = seg[prefix..]
        .iter()
        .rev()
        .zip(normal[prefix..].iter().rev())
        .take_while(|(a, b)| a == b)
        .count();
    let changed = &seg[prefix..seg.len() - suffix];
    let cp = changed
        .iter()
        .copied()
        .find(|&c| !is_boundary(c))
        .or_else(|| changed.first().copied())
        .unwrap_or(seg[0]);
    Some(NotNfc {
        start: at + prefix,
        end: at + seg.len() - suffix,
        nfc: normal[prefix..normal.len() - suffix].iter().collect(),
        cp,
    })
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::nfc_vectors::NFC_VECTORS;
    use crate::unicode_tables::UNICODE_VERSION;

    #[test]
    fn the_tables_are_unicode_16() {
        // Spec §5.1: v0.1 pins Unicode 16.0.
        assert_eq!(UNICODE_VERSION, "16.0.0");
        for table in [UNASSIGNED, NFC_QC_NO, NFC_QC_MAYBE, EXTENDED_PICTOGRAPHIC] {
            assert!(
                table.windows(2).all(|w| w[0].1 < w[1].0),
                "sorted, disjoint"
            );
        }
        assert!(DECOMPOSITION.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(COMPOSITION
            .windows(2)
            .all(|w| (w[0].0, w[0].1) < (w[1].0, w[1].1)));
    }

    #[test]
    fn nfc_matches_python_on_every_vector() {
        assert!(NFC_VECTORS.len() > 5000);
        let mut wrong = Vec::new();
        for &(input, expected) in NFC_VECTORS {
            if nfc(input) != expected {
                wrong.push((input, expected, nfc(input)));
            }
        }
        assert!(
            wrong.is_empty(),
            "{} wrong: {:?}",
            wrong.len(),
            &wrong[..wrong.len().min(5)]
        );
    }

    #[test]
    fn the_segment_check_agrees_with_whole_text_normalization() {
        // Every vector, alone and between ASCII and Arabic context: the text is NFC exactly
        // when no segment is reported, and applying the reported replacements gives NFC.
        for &(input, expected) in NFC_VECTORS {
            for text in [
                input.to_string(),
                format!("x = \"{input}\" \u{0627}{input}b\n"),
            ] {
                let chars: Vec<(usize, char)> = text.char_indices().collect();
                let runs = not_nfc(&chars);
                let whole = nfc(&text);
                assert_eq!(runs.is_empty(), whole == text, "{text:?}");
                let mut fixed = String::new();
                let mut at = 0;
                for r in &runs {
                    fixed.extend(chars[at..r.start].iter().map(|&(_, c)| c));
                    fixed.push_str(&r.nfc);
                    at = r.end;
                    assert!(chars[r.start..r.end].iter().any(|&(_, c)| c == r.cp));
                }
                fixed.extend(chars[at..].iter().map(|&(_, c)| c));
                assert_eq!(fixed, whole, "{text:?}");
            }
            assert_eq!(not_nfc(&chars_of(expected)).len(), 0, "{expected:?}");
        }
    }

    fn chars_of(s: &str) -> Vec<(usize, char)> {
        s.char_indices().collect()
    }

    #[test]
    fn unassigned_follows_unicode_16() {
        for c in [
            '\u{0378}',
            '\u{0380}',
            '\u{FDD0}',
            '\u{10FFFF}',
            '\u{A7CE}',
            '\u{088F}',
        ] {
            assert!(is_unassigned(c), "{c:?}");
        }
        // Assigned in 16.0 (U+1C89 CYRILLIC CAPITAL LETTER TJE is new in 16.0).
        for c in [
            'a',
            '\u{0377}',
            '\u{0627}',
            '\u{1C89}',
            '\u{1F600}',
            '\u{E000}',
        ] {
            assert!(!is_unassigned(c), "{c:?}");
        }
    }
}
